// Generated by scripts/embed.mjs from typst/, css/edu.css and examples/. Don't edit.

export const FILES: Record<string, string> = {
  "answers.typ": "// Answer spaces and answers. Answers appear only when the input `showAnswers` is \"true\":\n// written into the space in the accent color, and listed by `answer-key()`.\n#import \"util.typ\": _accent, _answers-shown, _css, _el, _html, _length, _question, _rule\n#import \"i18n.typ\": _start-side, _word\n\n/// Records an answer for `answer-key()`, under the question it is in.\n#let _record(kind, value) = [#metadata((kind: kind, value: value)) <edu-answer>]\n\n/// An inline blank to fill in, e.g. in a sentence or after an equals sign. When answers are shown,\n/// the answer is written on it.\n///\n/// - width (length): Width of the line. It grows to fit a shown answer.\n/// - answer (content, none): The expected answer.\n///\n/// ```example\n/// Water boils at #blank(answer: [100]) \u00b0C at sea level.\n/// ```\n#let blank(width: 4em, answer: none) = {\n  if answer != none { _record(\"blank\", answer) }\n  let width = _length(width, 4em)\n  let shown = _answers-shown and answer != none\n  context if _html() {\n    _el(\"span\", \"edu-blank\", if shown { _el(\"span\", \"edu-ink\", answer) } else { [ ] }, style: \"min-width: \" + _css(width))\n  } else {\n    let body = if shown { text(fill: _accent, answer) } else { none }\n    let w = if shown { calc.max(width.to-absolute(), measure(body).width + 0.6em.to-absolute()) } else { width }\n    box(width: w, stroke: (bottom: 0.5pt + _rule), outset: (bottom: 0.25em), inset: (x: 0.3em), align(center, body))\n  }\n}\n\n/// Ruled lines for a written answer of a sentence or more, across the full width.\n///\n/// - count (int): Number of lines.\n/// - spacing (length): Distance between lines.\n/// - answer (content, none): A model answer, written on the lines when answers are shown.\n///\n/// ```example\n/// Explain why the Moon has phases.\n/// #answer-lines(count: 3, answer: [We see different parts of its sunlit half as it orbits Earth.])\n/// ```\n#let answer-lines(count: 3, spacing: 2em, answer: none) = {\n  if answer != none { _record(\"lines\", answer) }\n  let spacing = _length(spacing, 2em)\n  let count = if type(count) == int { calc.clamp(count, 0, 200) } else { 3 }\n  let shown = _answers-shown and answer != none\n  context if _html() {\n    _el(\n      \"div\",\n      \"edu-lines\",\n      if shown { _el(\"span\", \"edu-ink\", answer) } else { none },\n      style: \"min-height: \" + _css(spacing * count) + \"; --edu-line: \" + _css(spacing),\n    )\n  } else {\n    // Text set on the lines: the first baseline one spacing down, then one line per spacing.\n    let pitch = spacing.to-absolute()\n    block(width: 100%, height: pitch * count + 0.3em, breakable: false, above: 0.8em, below: 0.8em, {\n      for i in range(count) {\n        place(top, dy: pitch * (i + 1) + 0.25em, line(length: 100%, stroke: 0.4pt + _rule))\n      }\n      if shown {\n        set text(fill: _accent, top-edge: 1em, bottom-edge: 0em)\n        set par(leading: pitch - 1em.to-absolute(), justify: false)\n        v(pitch - 1em)\n        pad(x: 0.3em, answer)\n      }\n    })\n  }\n}\n\n/// Empty space for working, a drawing or a calculation.\n///\n/// - height (length): Height of the space. It grows to fit a shown answer.\n/// - boxed (bool): Draw a frame around the space.\n/// - answer (content, none): A worked answer, written in the space when answers are shown.\n///\n/// ```example\n/// Solve $3x + 4 = 19$. Show your working.\n/// #answer-space(height: 5em, answer: [$3x = 15$, so $x = 5$.])\n/// ```\n#let answer-space(height: 4em, boxed: false, answer: none) = {\n  if answer != none { _record(\"space\", answer) }\n  let height = _length(height, 4em)\n  let shown = _answers-shown and answer != none\n  let stroke = if boxed { 0.5pt + _rule } else { none }\n  context if _html() {\n    _el(\n      \"div\",\n      if boxed { (\"edu-space\", \"edu-boxed\") } else { \"edu-space\" },\n      if shown { _el(\"div\", \"edu-ink\", answer) } else { none },\n      style: \"min-height: \" + _css(height),\n    )\n  } else if shown {\n    layout(size => {\n      let inner = block(width: size.width, inset: 6pt, text(fill: _accent, answer))\n      block(width: 100%, height: calc.max(height.to-absolute(), measure(inner).height), stroke: stroke, inner)\n    })\n  } else {\n    block(width: 100%, height: height, stroke: stroke, breakable: false)\n  }\n}\n\n/// A worked solution or explanation, shown only when answers are shown. Use it for anything a\n/// teacher's copy should add: full solutions, marking notes, expected points.\n///\n/// ```example\n/// #answer[The ratio is $3 : 4$ because both sides divide by 5.]\n/// ```\n#let answer(body) = {\n  _record(\"answer\", body)\n  if _answers-shown { context if _html() {\n    _el(\"div\", \"edu-answer\", [#_el(\"span\", \"edu-answer-label\", _word(\"answer\") + \":\") #body])\n  } else {\n    let side = _start-side()\n    block(\n      width: 100%,\n      inset: (x: 8pt, y: 6pt),\n      fill: _accent.lighten(92%),\n      stroke: ((side): 2pt + _accent),\n      text(fill: _accent)[*#_word(\"answer\"):* #body],\n    )\n  } }\n}\n\n/// The answers to every question, by question number, for a key at the end of the document.\n/// Like every answer it appears only when answers are shown, so it is safe in a student's copy.\n///\n/// - title (content, auto): Heading of the key. `auto` is \"Answer key\" in the document's language.\n///\n/// ```example\n/// #answer-key()\n/// ```\n#let answer-key(title: auto) = {\n  if not _answers-shown { return }\n  context {\n    let entries = query(<edu-answer>)\n    if entries.len() == 0 { return }\n    let heading-text = if title == auto { _word(\"answer-key\") } else { title }\n    // Group answers under their question's number, in document order; 0 is outside any question.\n    let groups = ()\n    for e in entries {\n      let n = _question.at(e.location()).first()\n      if groups.len() > 0 and groups.last().at(0) == n { groups.at(-1).at(1).push(e.value.value) } else {\n        groups.push((n, (e.value.value,)))\n      }\n    }\n    let items = groups.map(((n, values)) => {\n      let body = values.join([; ])\n      if n == 0 { body } else { [*#numbering(\"1.\", n)* #body] }\n    })\n    if _html() {\n      _el(\"section\", \"edu-key\", {\n        html.elem(\"h2\", heading-text)\n        for item in items { html.elem(\"p\", item) }\n      })\n    } else {\n      block(width: 100%, above: 1.5em, {\n        text(weight: \"bold\", size: 1.2em, heading-text)\n        set text(fill: _accent)\n        for item in items { block(above: 0.7em, item) }\n      })\n    }\n  }\n}\n",
  "blocks.typ": "// Teaching content: callouts, instructions, learning objectives, rubrics, student fields.\n#import \"util.typ\": _array, _el, _html, _rule\n#import \"i18n.typ\": _field-label, _start-side, _word, _words\n\n#let _kinds = (\n  note: rgb(\"#2563eb\"),\n  tip: rgb(\"#15803d\"),\n  warning: rgb(\"#c2410c\"),\n  definition: rgb(\"#7c3aed\"),\n  example: rgb(\"#0f766e\"),\n  remember: rgb(\"#b45309\"),\n)\n\n// A thin frame with its label set into the top edge on the starting side, like a fieldset's\n// legend: it groups without filling the page with colour, and it prints in black and white.\n#let _framed(color, label, body) = context {\n  let side = _start-side()\n  let inset = (x: 11pt, top: if label == none { 9pt } else { 11pt }, bottom: 9pt)\n  // The label's box covers the stroke in the page's colour.\n  let paper = if page.fill in (auto, none) { white } else { page.fill }\n  block(\n    width: 100%,\n    above: if label == none { 1.1em } else { 1.6em },\n    below: 1.1em,\n    inset: inset,\n    stroke: 0.8pt + color,\n    radius: 4pt,\n    {\n      if label != none {\n        let tab = box(fill: paper, inset: (x: 4pt, y: 1pt), label)\n        // Centred on the stroke: half the label's height above the frame's top edge.\n        let h = measure(tab).height\n        let (align, dx) = if side == \"left\" { (left, -4pt) } else { (right, 4pt) }\n        place(top + align, dx: dx, dy: -inset.top - h / 2, tab)\n      }\n      body\n    },\n  )\n}\n\n/// A highlighted box for a note, tip, warning, definition, worked example or something to\n/// remember. Its title defaults to the kind's name in the document's language.\n///\n/// - kind (str): One of \"note\", \"tip\", \"warning\", \"definition\", \"example\", \"remember\".\n/// - title (content, auto, none): The box's title.\n///\n/// ```example\n/// #callout(kind: \"definition\")[A *prime number* has exactly two factors: 1 and itself.]\n/// ```\n#let callout(kind: \"note\", title: auto, body) = {\n  let kind = if kind in _kinds { kind } else { \"note\" }\n  let color = _kinds.at(kind)\n  context {\n    let title = if title == auto { _word(kind) } else { title }\n    if _html() {\n      _el(\"aside\", (\"edu-callout\", \"edu-\" + kind), role: \"note\", {\n        if title != none { _el(\"div\", \"edu-callout-title\", title) }\n        body\n      })\n    } else {\n      _framed(color, if title != none { text(weight: \"bold\", fill: color, title) }, body)\n    }\n  }\n}\n\n/// Instructions for students, in a framed box titled \"Instructions\" in the document's language.\n///\n/// ```example\n/// #instructions[\n///   - Answer *all* questions.\n///   - Show your working.\n/// ]\n/// ```\n#let instructions(body) = context {\n  if _html() {\n    _el(\"aside\", (\"edu-callout\", \"edu-instructions\"), role: \"note\", {\n      _el(\"div\", \"edu-callout-title\", _word(\"instructions\"))\n      body\n    })\n  } else {\n    _framed(_rule, strong(_word(\"instructions\")), body)\n  }\n}\n\n/// What students will learn, as a titled box. Write the objectives as a list.\n///\n/// ```example\n/// #learning-objectives[\n///   - Describe the stages of the water cycle.\n///   - Explain how the Sun drives evaporation.\n/// ]\n/// ```\n#let learning-objectives(body) = callout(kind: \"tip\", title: context _word(\"objectives\"), body)\n\n/// A grading rubric: one row per criterion, one column per level. Give each criterion as\n/// `(name, description for the first level, the next level, \u2026)`.\n///\n/// - levels (array, auto): Level names, best first. `auto`: four levels named in the document's language.\n/// - points (array, auto, none): Points per level. `auto` counts down to 1; `none` hides them.\n///\n/// ```example\n/// #rubric(\n///   ([Thesis], [Clear and arguable.], [Clear.], [Vague.], [Missing.]),\n///   ([Evidence], [Strong, cited.], [Relevant.], [Thin.], [None.]),\n/// )\n/// ```\n#let rubric(..criteria, levels: auto, points: auto) = context {\n  let criteria = criteria.pos().map(c => if type(c) == array { c } else { (c,) })\n  let levels = if levels == auto { _words.at(text.lang, default: _words.en).levels } else { _array(levels) }\n  let n = levels.len()\n  let points = if points == auto { range(n, 0, step: -1) } else if points != none { _array(points) }\n  let head(i) = if points == none { levels.at(i) } else { [#levels.at(i) (#points.at(i, default: \"\"))] }\n  let cells(c) = range(n).map(i => c.at(i + 1, default: []))\n  if _html() {\n    _el(\"table\", \"edu-rubric\", {\n      html.elem(\"thead\", html.elem(\"tr\", {\n        html.elem(\"th\", attrs: (scope: \"col\"), _word(\"criteria\"))\n        for i in range(n) { html.elem(\"th\", attrs: (scope: \"col\"), head(i)) }\n      }))\n      html.elem(\"tbody\", for c in criteria {\n        html.elem(\"tr\", {\n          html.elem(\"th\", attrs: (scope: \"row\"), c.at(0, default: []))\n          for cell in cells(c) { html.elem(\"td\", cell) }\n        })\n      })\n    })\n  } else {\n    set text(size: 0.9em)\n    table(\n      columns: (1.1fr,) + (1fr,) * n,\n      inset: 6pt,\n      stroke: 0.5pt + _rule,\n      fill: (x, y) => if y == 0 { luma(235) } else if x == 0 { luma(248) },\n      table.header(strong(_word(\"criteria\")), ..range(n).map(i => strong(head(i)))),\n      ..criteria.map(c => (strong(c.at(0, default: [])), ..cells(c))).flatten(),\n    )\n  }\n}\n\n/// Lines for students to write their name, the date, their class, and so on. Known fields are\n/// \"name\", \"date\", \"class\", \"section\", \"roll\", \"score\" and \"teacher\", labelled in the document's\n/// language; any other text is used as its own label. The name field gets the most room.\n///\n/// ```example\n/// #student-info(\"name\", \"class\", \"roll\")\n/// ```\n#let student-info(..fields) = context {\n  let fields = if fields.pos().len() == 0 { (\"name\", \"date\", \"class\") } else { fields.pos() }\n  if _html() {\n    _el(\"div\", \"edu-info\", for f in fields {\n      _el(\"span\", \"edu-field\", [#_field-label(f):#_el(\"span\", \"edu-blank\", [ ])])\n    })\n  } else {\n    let width(f) = if f == \"name\" { 2.2fr } else { 1fr }\n    block(above: 1em, below: 1em, grid(\n      columns: fields.map(f => (auto, width(f))).flatten(),\n      // Tight between a label and its line, wider between fields.\n      column-gutter: range(fields.len() * 2 - 1).map(i => if calc.even(i) { 0.4em } else { 1.2em }),\n      ..fields\n        .map(f => (\n          [#_field-label(f):],\n          box(width: 100%, stroke: (bottom: 0.5pt + _rule), outset: (bottom: 0.25em), h(1fr)),\n        ))\n        .flatten(),\n    ))\n  }\n}\n",
  "chem.typ": "// Chemical formulas and equations from plain text, a small subset of LaTeX's mhchem. The result\n// is math, so HTML export writes MathML.\n#import \"util.typ\": _plain\n\n#let _is-upper(c) = c.match(regex(\"^\\p{Lu}$\")) != none\n#let _is-lower(c) = c.match(regex(\"^\\p{Ll}$\")) != none\n#let _is-digit(c) = c.match(regex(\"^[0-9]$\")) != none\n\n/// Upright text in math.\n#let _up(s) = math.upright(s)\n\n#let _states = (\"aq\", \"s\", \"l\", \"g\")\n\n/// One species, e.g. `2H2O`, `SO4^2-`, `Na+`, `CuSO4*5H2O`, `Fe(OH)3`, `e-`.\n#let _species(s) = {\n  let cs = s.clusters()\n  let n = cs.len()\n  let out = ()\n  let i = 0\n  // Leading coefficient: digits, or a fraction such as 1/2.\n  let coef = \"\"\n  while i < n and (_is-digit(cs.at(i)) or (cs.at(i) == \"/\" and coef != \"\")) {\n    coef += cs.at(i)\n    i += 1\n  }\n  if coef != \"\" {\n    out.push(if \"/\" in coef and not coef.ends-with(\"/\") {\n      let (a, b) = coef.split(\"/\")\n      math.frac(_up(a), _up(b))\n    } else { _up(coef) })\n  }\n  // A stack of open groups; each holds its units so far. Units are (base, sub, sup).\n  let stack = ((),)\n  let attach(u) = math.attach(u.at(0), b: u.at(1), t: u.at(2))\n  while i < n {\n    let c = cs.at(i)\n    if _is-upper(c) {\n      let el = c\n      i += 1\n      while i < n and _is-lower(cs.at(i)) {\n        el += cs.at(i)\n        i += 1\n      }\n      stack.at(-1).push((_up(el), none, none))\n    } else if c == \"e\" and stack.len() == 1 and stack.at(-1).len() == 0 {\n      // An electron: e-, e^-.\n      stack.at(-1).push((math.italic(\"e\"), none, none))\n      i += 1\n    } else if _is-digit(c) {\n      let d = \"\"\n      while i < n and _is-digit(cs.at(i)) {\n        d += cs.at(i)\n        i += 1\n      }\n      // Digits after a unit are its subscript; after a dot (hydrate) they are a coefficient.\n      let last = stack.at(-1).at(-1, default: none)\n      if last != none and last.at(0) != sym.dot.c and last.at(1) == none and last.at(2) == none {\n        stack.at(-1).at(-1).at(1) = _up(d)\n      } else { stack.at(-1).push((_up(d), none, none)) }\n    } else if c in (\"(\", \"[\") {\n      // A state symbol: (aq), (s), (l), (g).\n      let close = cs.slice(i).position(x => x == \")\")\n      let inner = if close != none { cs.slice(i + 1, i + close).join(default: \"\") }\n      if c == \"(\" and inner in _states {\n        stack.at(-1).push((_up(\"(\" + inner + \")\"), none, none))\n        i += close + 1\n      } else {\n        stack.push(())\n        i += 1\n      }\n    } else if c in (\")\", \"]\") and stack.len() > 1 {\n      let units = stack.pop()\n      let open = if c == \")\" { \"(\" } else { \"[\" }\n      stack.at(-1).push(([#_up(open)#units.map(attach).join()#_up(c)], none, none))\n      i += 1\n    } else if c == \"^\" {\n      // A charge: ^2+, ^-, ^{3-}.\n      i += 1\n      let charge = \"\"\n      if i < n and cs.at(i) == \"{\" {\n        i += 1\n        while i < n and cs.at(i) != \"}\" {\n          charge += cs.at(i)\n          i += 1\n        }\n        i += 1\n      } else {\n        while i < n and (_is-digit(cs.at(i)) or cs.at(i) in (\"+\", \"-\")) {\n          charge += cs.at(i)\n          i += 1\n        }\n      }\n      let charge = charge.replace(\"-\", \"\\u{2212}\")\n      if stack.at(-1).len() > 0 { stack.at(-1).at(-1).at(2) = _up(charge) }\n    } else if c in (\"+\", \"-\") and stack.at(-1).len() > 0 {\n      // A charge written without ^ at the end: Na+, Cl-, O2-- is not supported.\n      let charge = cs.slice(i).filter(x => x in (\"+\", \"-\")).join(default: \"\")\n      stack.at(-1).at(-1).at(2) = _up(charge.replace(\"-\", \"\\u{2212}\"))\n      i += charge.len()\n    } else if c in (\"*\", \".\", \"\u00b7\") {\n      stack.at(-1).push((sym.dot.c, none, none))\n      i += 1\n    } else {\n      stack.at(-1).push((_up(c), none, none))\n      i += 1\n    }\n  }\n  // Unclosed groups (a formula cut off while streaming) close themselves.\n  while stack.len() > 1 {\n    let units = stack.pop()\n    stack.at(-1).push(([#_up(\"(\")#units.map(attach).join()], none, none))\n  }\n  out + stack.at(0).map(attach)\n}\n\n#let _tokens = (\n  \"+\": sym.plus,\n  \"->\": sym.arrow.r.long,\n  \"\u2192\": sym.arrow.r.long,\n  \"<-\": sym.arrow.l.long,\n  \"<->\": sym.arrow.l.r.long,\n  \"<=>\": sym.harpoons.rtlb,\n  \"\u21cc\": sym.harpoons.rtlb,\n  \"=\": sym.eq,\n  \"^\": sym.arrow.t,\n  \"v\": sym.arrow.b,\n)\n\n/// A chemical formula or equation from plain text: digits after an element are subscripts, a\n/// leading number is a coefficient, `^2+` or a trailing `+`/`-` is a charge, `(aq)`, `(s)`,\n/// `(l)`, `(g)` are states, `*` is a hydrate's dot, and `->`, `<=>`, `<-` are arrows. Separate\n/// species, `+` and arrows with spaces. Works in text and in math.\n///\n/// ```example\n/// #ce(\"2H2 + O2 -> 2H2O\") and #ce(\"CH3COOH <=> CH3COO- + H+\"); copper sulfate is #ce(\"CuSO4*5H2O\").\n/// ```\n#let ce(formula) = {\n  let s = if type(formula) == str { formula } else { _plain(formula) }\n  let parts = s.split(\" \").filter(t => t != \"\").map(t => if t in _tokens { (_tokens.at(t),) } else { _species(t) })\n  if parts.len() == 0 { return }\n  math.equation(block: false, numbering: none, parts.flatten().join())\n}\n",
  "drawings.typ": "// Drawings worksheets need: number lines, graph paper, coordinate planes. Native shapes, so they\n// need no package; in HTML each is one inline SVG (`html.frame`) with a description for screen\n// readers. They run left to right in every language, as in printed maths in Arabic and Bengali.\n#import \"util.typ\": _array, _drawing, _faint, _length, _pairs, _rule\n\n/// A number as a label: whole floats without \".0\", and a real minus sign.\n#let _num(v) = {\n  let v = if type(v) == float { calc.round(v, digits: 6) } else { v }\n  if type(v) == float and v == calc.round(v) { str(int(v)) } else { str(v) }\n}\n\n/// A label centred on a point, given in the drawing's coordinates.\n#let _label-at(x, y, body, size: 0.8em) = place(top + left, dx: x - 1.5cm, dy: y, box(width: 3cm, align(\n  center,\n  text(size: size, body),\n)))\n\n#let _dot(x, y, open: false, r: 3pt) = place(top + left, dx: x - r, dy: y - r, circle(\n  radius: r,\n  fill: if open { white } else { black },\n  stroke: if open { 1pt + black } else { none },\n))\n\n/// A horizontal arrowhead at (x, y), pointing right (`dir: 1`) or left (`dir: -1`).\n#let _arrow-x(x, y, dir: 1) = place(top + left, polygon(\n  fill: black,\n  (x, y),\n  (x - dir * 6pt, y - 3pt),\n  (x - dir * 6pt, y + 3pt),\n))\n\n/// A vertical arrowhead at (x, y), pointing up.\n#let _arrow-up(x, y) = place(top + left, polygon(fill: black, (x, y), (x - 3pt, y + 6pt), (x + 3pt, y + 6pt)))\n\n/// A number line with ticks every `step`, numbered, with arrows at both ends. Mark answers or\n/// examples with filled `points` and hollow `open-points` (as in inequalities), and name values\n/// with `marks`.\n///\n/// - from (int, float): Leftmost value.\n/// - to (int, float): Rightmost value.\n/// - step (int, float): Distance between ticks.\n/// - length (length): Length of the line.\n/// - labels (auto, none, array): Which ticks are numbered. `auto` numbers every tick (every 5th or\n///   10th on long lines); `none` numbers none, for students to fill in; an array lists values,\n///   or `(value, label)` pairs such as `(0.5, $1/2$)`.\n/// - points (array): Values marked with a filled dot.\n/// - open-points (array): Values marked with a hollow dot.\n/// - marks (array): `(value, label)` pairs written above the line.\n///\n/// ```example\n/// #number-line(from: -5, to: 5, points: (2,), open-points: (-1,), marks: ((2, [A]),))\n/// ```\n#let number-line(\n  from: 0,\n  to: 10,\n  step: 1,\n  length: 12cm,\n  labels: auto,\n  points: (),\n  open-points: (),\n  marks: (),\n) = context {\n  if to <= from or step <= 0 { return }\n  let number(v) = type(v) in (int, float)\n  let points = _array(points).filter(number)\n  let open-points = _array(open-points).filter(number)\n  let marks = _pairs(marks).filter(m => m.len() > 0 and number(m.at(0))).map(m => (m.at(0), m.at(1, default: none)))\n  let count = calc.min(int(calc.floor((to - from) / step + 1e-9)), 400)\n  let length = _length(length, 12cm).to-absolute()\n  let pad = 0.7cm\n  let x(v) = pad + (v - from) / (to - from) * length\n  let y = 0.9cm\n  let value(i) = from + i * step\n  let every = if count <= 20 { 1 } else if count <= 60 { 5 } else { 10 }\n  // Labels as (value, content) pairs.\n  let labelled = if labels == none { () } else if labels == auto {\n    range(count + 1).filter(i => calc.rem(i, every) == 0).map(i => (value(i), _num(value(i))))\n  } else {\n    _array(labels)\n      .map(l => if type(l) == array { (l.at(0, default: none), l.at(1, default: none)) } else { (l, none) })\n      .filter(((v, _)) => number(v))\n      .map(((v, l)) => (v, if l == none { _num(v) } else { l }))\n  }\n  let description = (\n    \"Number line from \" + _num(from) + \" to \" + _num(to) + \", step \" + _num(step)\n      + if points.len() > 0 { \"; points at \" + points.map(_num).join(\", \") } else { \"\" }\n      + if open-points.len() > 0 { \"; open points at \" + open-points.map(_num).join(\", \") } else { \"\" }\n  )\n  let drawing = box(width: length + 2 * pad, height: 1.6cm, {\n    place(top + left, line(start: (0.15cm, y), end: (length + 2 * pad - 0.15cm, y), stroke: 0.8pt))\n    _arrow-x(length + 2 * pad - 0.1cm, y)\n    _arrow-x(0.1cm, y, dir: -1)\n    for i in range(count + 1) {\n      let tall = labels == auto and calc.rem(i, every) == 0\n      place(top + left, line(start: (x(value(i)), y - 4pt), end: (x(value(i)), y + if tall { 5pt } else { 4pt }), stroke: 0.6pt))\n    }\n    for (v, l) in labelled { _label-at(x(v), y + 7pt, l) }\n    for (v, l) in marks {\n      place(top + left, line(start: (x(v), y - 6pt), end: (x(v), y + 6pt), stroke: 1.2pt))\n      if l != none { _label-at(x(v), y - 22pt, l, size: 0.9em) }\n    }\n    for v in points { _dot(x(v), y) }\n    for v in open-points { _dot(x(v), y, open: true) }\n  })\n  block(above: 1em, below: 1em, _drawing(drawing, label: description))\n}\n\n/// Squared paper for drawing graphs, shapes or bar charts, with a darker line every `major` squares.\n///\n/// - cols (int): Squares across.\n/// - rows (int): Squares down.\n/// - step (length): Side of a square.\n/// - major (int, none): Darker line every this many squares; `none` for none.\n///\n/// ```example\n/// #graph-paper(cols: 20, rows: 8)\n/// ```\n#let graph-paper(cols: 30, rows: 10, step: 5mm, major: 5) = context {\n  let cols = if type(cols) == int { calc.clamp(cols, 1, 200) } else { 30 }\n  let rows = if type(rows) == int { calc.clamp(rows, 1, 200) } else { 10 }\n  let step = _length(step, 5mm).to-absolute()\n  let w = cols * step\n  let h = rows * step\n  let stroke(i, last) = if i == 0 or i == last or (major != none and calc.rem(i, major) == 0) { 0.6pt + _rule } else {\n    0.3pt + _faint\n  }\n  let drawing = box(width: w, height: h, {\n    for i in range(cols + 1) { place(top + left, line(start: (i * step, 0pt), end: (i * step, h), stroke: stroke(i, cols))) }\n    for j in range(rows + 1) { place(top + left, line(start: (0pt, j * step), end: (w, j * step), stroke: stroke(j, rows))) }\n  })\n  block(above: 1em, below: 1em, _drawing(drawing, label: \"Graph paper, \" + str(cols) + \" by \" + str(rows) + \" squares\"))\n}\n\n/// A coordinate plane on a square grid, with numbered x and y axes. Plot `points` as `(x, y)` or\n/// `(x, y, label)`.\n///\n/// - x (array): The x range, `(min, max)`.\n/// - y (array): The y range, `(min, max)`.\n/// - unit (length): Size of one unit.\n/// - grid (bool): Draw grid lines.\n/// - labels (bool): Number the axes.\n/// - points (array): Points to plot.\n///\n/// ```example\n/// #coordinate-plane(x: (-4, 4), y: (-3, 3), points: ((1, 2, [A]), (-3, -1, [B])))\n/// ```\n#let coordinate-plane(x: (-5, 5), y: (-5, 5), unit: 7mm, grid: true, labels: true, points: ()) = context {\n  let (x, y) = (_array(x), _array(y))\n  let (x0, x1) = (int(x.at(0, default: -5)), int(x.at(1, default: 5)))\n  let (y0, y1) = (int(y.at(0, default: -5)), int(y.at(1, default: 5)))\n  if x1 <= x0 or y1 <= y0 { return }\n  // A point still being typed, `(1,)`, has no y yet.\n  let points = _pairs(points).filter(p => p.len() >= 2 and p.slice(0, 2).all(v => type(v) in (int, float)))\n  // Keep a runaway range from drawing thousands of lines.\n  let (x0, x1, y0, y1) = (calc.max(x0, x1 - 60), x1, calc.max(y0, y1 - 60), y1)\n  let u = _length(unit, 7mm).to-absolute()\n  let pad = 0.8cm\n  let px(v) = pad + (v - x0) * u\n  let py(v) = pad + (y1 - v) * u\n  let w = (x1 - x0) * u + 2 * pad\n  let h = (y1 - y0) * u + 2 * pad\n  // The axes cross at the origin, or at the nearest edge when 0 is out of range.\n  let ox = px(calc.clamp(0, x0, x1))\n  let oy = py(calc.clamp(0, y0, y1))\n  let every(span) = if span <= 14 { 1 } else if span <= 30 { 2 } else { 5 }\n  let description = (\n    \"Coordinate plane, x from \" + str(x0) + \" to \" + str(x1) + \", y from \" + str(y0) + \" to \" + str(y1)\n      + if points.len() > 0 {\n        \"; points \" + points.map(p => \"(\" + _num(p.at(0)) + \", \" + _num(p.at(1)) + \")\").join(\", \")\n      } else { \"\" }\n  )\n  let drawing = box(width: w, height: h, {\n    if grid {\n      for i in range(x0, x1 + 1) { place(top + left, line(start: (px(i), py(y1)), end: (px(i), py(y0)), stroke: 0.3pt + _faint)) }\n      for j in range(y0, y1 + 1) { place(top + left, line(start: (px(x0), py(j)), end: (px(x1), py(j)), stroke: 0.3pt + _faint)) }\n    }\n    place(top + left, line(start: (px(x0) - 0.4cm, oy), end: (px(x1) + 0.5cm, oy), stroke: 0.8pt))\n    place(top + left, line(start: (ox, py(y0) + 0.4cm), end: (ox, py(y1) - 0.5cm), stroke: 0.8pt))\n    _arrow-x(px(x1) + 0.55cm, oy)\n    _arrow-up(ox, py(y1) - 0.55cm)\n    _label-at(px(x1) + 0.55cm, oy + 3pt, text(style: \"italic\")[x])\n    place(top + left, dx: ox + 5pt, dy: py(y1) - 0.75cm, text(size: 0.8em, style: \"italic\")[y])\n    if labels {\n      for i in range(x0, x1 + 1) {\n        if i != 0 and calc.rem(i, every(x1 - x0)) == 0 {\n          place(top + left, line(start: (px(i), oy - 2pt), end: (px(i), oy + 2pt), stroke: 0.6pt))\n          _label-at(px(i), oy + 4pt, _num(i), size: 0.7em)\n        }\n      }\n      for j in range(y0, y1 + 1) {\n        if j != 0 and calc.rem(j, every(y1 - y0)) == 0 {\n          place(top + left, line(start: (ox - 2pt, py(j)), end: (ox + 2pt, py(j)), stroke: 0.6pt))\n          place(top + left, dx: ox - 1.05cm, dy: py(j) - 0.5em, box(width: 1cm, align(right, text(size: 0.7em, _num(j)))))\n        }\n      }\n      if x0 <= 0 and 0 <= x1 and y0 <= 0 and 0 <= y1 {\n        place(top + left, dx: ox - 1.05cm, dy: oy + 2pt, box(width: 1cm, align(right, text(size: 0.7em, \"0\"))))\n      }\n    }\n    for p in points {\n      _dot(px(p.at(0)), py(p.at(1)), r: 2.2pt)\n      if p.len() > 2 { place(top + left, dx: px(p.at(0)) + 4pt, dy: py(p.at(1)) - 1.15em, text(size: 0.85em, p.at(2))) }\n    }\n  })\n  block(above: 1em, below: 1em, _drawing(drawing, label: description))\n}\n",
  "i18n.typ": "// Words edu writes itself (field labels, callout titles, True/False, points), in the launch\n// languages: English, Arabic and Bengali (#1). Picked by `text.lang`, English otherwise.\n// The Arabic and Bengali wording is a first draft and needs a native speaker's review.\n\n#let _words = (\n  en: (\n    name: \"Name\",\n    date: \"Date\",\n    class: \"Class\",\n    section: \"Section\",\n    roll: \"Roll no.\",\n    score: \"Score\",\n    teacher: \"Teacher\",\n    subject: \"Subject\",\n    grade: \"Grade\",\n    duration: \"Duration\",\n    total: \"Total\",\n    answer: \"Answer\",\n    answer-key: \"Answer key\",\n    instructions: \"Instructions\",\n    objectives: \"Learning objectives\",\n    note: \"Note\",\n    tip: \"Tip\",\n    warning: \"Warning\",\n    definition: \"Definition\",\n    example: \"Example\",\n    remember: \"Remember\",\n    \"true\": \"True\",\n    \"false\": \"False\",\n    criteria: \"Criteria\",\n    candidate: \"Candidate\",\n    levels: (\"Exemplary\", \"Proficient\", \"Developing\", \"Beginning\"),\n  ),\n  ar: (\n    name: \"\u0627\u0644\u0627\u0633\u0645\",\n    date: \"\u0627\u0644\u062a\u0627\u0631\u064a\u062e\",\n    class: \"\u0627\u0644\u0641\u0635\u0644\",\n    section: \"\u0627\u0644\u0634\u0639\u0628\u0629\",\n    roll: \"\u0631\u0642\u0645 \u0627\u0644\u062c\u0644\u0648\u0633\",\n    score: \"\u0627\u0644\u062f\u0631\u062c\u0629\",\n    teacher: \"\u0627\u0644\u0645\u0639\u0644\u0645\",\n    subject: \"\u0627\u0644\u0645\u0627\u062f\u0629\",\n    grade: \"\u0627\u0644\u0635\u0641\",\n    duration: \"\u0627\u0644\u0632\u0645\u0646\",\n    total: \"\u0627\u0644\u0645\u062c\u0645\u0648\u0639\",\n    answer: \"\u0627\u0644\u0625\u062c\u0627\u0628\u0629\",\n    answer-key: \"\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0625\u062c\u0627\u0628\u0629\",\n    instructions: \"\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a\",\n    objectives: \"\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u0639\u0644\u0645\",\n    note: \"\u0645\u0644\u0627\u062d\u0638\u0629\",\n    tip: \"\u0646\u0635\u064a\u062d\u0629\",\n    warning: \"\u062a\u0646\u0628\u064a\u0647\",\n    definition: \"\u062a\u0639\u0631\u064a\u0641\",\n    example: \"\u0645\u062b\u0627\u0644\",\n    remember: \"\u062a\u0630\u0643\u0631\",\n    \"true\": \"\u0635\u062d\",\n    \"false\": \"\u062e\u0637\u0623\",\n    criteria: \"\u0627\u0644\u0645\u0639\u064a\u0627\u0631\",\n    candidate: \"\u0627\u0644\u0637\u0627\u0644\u0628\",\n    levels: (\"\u0645\u062a\u0645\u064a\u0632\", \"\u0645\u062a\u0642\u0646\", \"\u0646\u0627\u0645\", \"\u0645\u0628\u062a\u062f\u0626\"),\n  ),\n  bn: (\n    name: \"\u09a8\u09be\u09ae\",\n    date: \"\u09a4\u09be\u09b0\u09bf\u0996\",\n    class: \"\u09b6\u09cd\u09b0\u09c7\u09a3\u09bf\",\n    section: \"\u09b6\u09be\u0996\u09be\",\n    roll: \"\u09b0\u09cb\u09b2 \u09a8\u0982\",\n    score: \"\u09aa\u09cd\u09b0\u09be\u09aa\u09cd\u09a4 \u09a8\u09ae\u09cd\u09ac\u09b0\",\n    teacher: \"\u09b6\u09bf\u0995\u09cd\u09b7\u0995\",\n    subject: \"\u09ac\u09bf\u09b7\u09af\u09bc\",\n    grade: \"\u09b6\u09cd\u09b0\u09c7\u09a3\u09bf\",\n    duration: \"\u09b8\u09ae\u09af\u09bc\",\n    total: \"\u09ae\u09cb\u099f\",\n    answer: \"\u0989\u09a4\u09cd\u09a4\u09b0\",\n    answer-key: \"\u0989\u09a4\u09cd\u09a4\u09b0\u09ae\u09be\u09b2\u09be\",\n    instructions: \"\u09a8\u09bf\u09b0\u09cd\u09a6\u09c7\u09b6\u09a8\u09be\",\n    objectives: \"\u09b6\u09bf\u0996\u09a8\u09ab\u09b2\",\n    note: \"\u09b2\u0995\u09cd\u09b7 \u0995\u09b0\u09cb\",\n    tip: \"\u09aa\u09b0\u09be\u09ae\u09b0\u09cd\u09b6\",\n    warning: \"\u09b8\u09a4\u09b0\u09cd\u0995\u09a4\u09be\",\n    definition: \"\u09b8\u0982\u099c\u09cd\u099e\u09be\",\n    example: \"\u0989\u09a6\u09be\u09b9\u09b0\u09a3\",\n    remember: \"\u09ae\u09a8\u09c7 \u09b0\u09be\u0996\u09cb\",\n    \"true\": \"\u09b8\u09a4\u09cd\u09af\",\n    \"false\": \"\u09ae\u09bf\u09a5\u09cd\u09af\u09be\",\n    criteria: \"\u09ae\u09be\u09a8\u09a6\u09a3\u09cd\u09a1\",\n    candidate: \"\u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be\u09b0\u09cd\u09a5\u09c0\",\n    levels: (\"\u099a\u09ae\u09ce\u0995\u09be\u09b0\", \"\u09a6\u0995\u09cd\u09b7\", \"\u0989\u09a8\u09cd\u09a8\u09af\u09bc\u09a8\u09b6\u09c0\u09b2\", \"\u09aa\u09cd\u09b0\u09be\u09b0\u09ae\u09cd\u09ad\u09bf\u0995\"),\n  ),\n)\n\n/// The word for `key` in the current language. Needs context.\n#let _word(key) = _words.at(text.lang, default: _words.en).at(key, default: _words.en.at(key, default: key))\n\n/// A student-field label: a known key (`\"name\"`) in the current language, anything else as given.\n#let _field-label(field) = if type(field) == str and field in _words.en { _word(field) } else { field }\n\n/// \"2 points\" in the current language, or with the template's own word (`points-label`).\n#let _points-text(n, word: auto) = {\n  if type(word) == function { return word(n) }\n  if word != auto { return [#n #word] }\n  if text.lang == \"ar\" {\n    // Arabic counts nouns by number: 1 and 2 have their own forms, 3\u201310 take the plural.\n    if n == 1 { \"\u062f\u0631\u062c\u0629 \u0648\u0627\u062d\u062f\u0629\" } else if n == 2 { \"\u062f\u0631\u062c\u062a\u0627\u0646\" } else if n >= 3 and n <= 10 { [#n \u062f\u0631\u062c\u0627\u062a] } else { [#n \u062f\u0631\u062c\u0629] }\n  } else if text.lang == \"bn\" { [#n \u09a8\u09ae\u09cd\u09ac\u09b0] } else if n == 1 { \"1 point\" } else { [#n points] }\n}\n\n/// Marker pattern for options and sub-parts: `(a)`, `(\u0623)`, `(\u0995)`.\n#let _letter-pattern() = if text.lang == \"ar\" { \"(\u0623)\" } else if text.lang == \"bn\" { \"(\u0995)\" } else { \"(a)\" }\n\n/// The marker of the `i`th option (1-based), without parentheses: `a`, `\u0623`, `\u0995`.\n#let _letter(i) = numbering(if text.lang == \"ar\" { \"\u0623\" } else if text.lang == \"bn\" { \"\u0995\" } else { \"a\" }, i)\n\n/// The text direction in effect: `text.dir` is `auto` unless set, so derive it from the language as Typst does.\n#let _dir() = if text.dir != auto { text.dir } else if text.lang in (\"ar\", \"fa\", \"he\", \"ur\", \"ps\", \"sd\", \"ug\", \"yi\", \"dv\") {\n  rtl\n} else { ltr }\n\n/// The physical side where lines start: `\"left\"` in LTR text, `\"right\"` in RTL (strokes and radii are physical).\n#let _start-side() = if _dir() == rtl { \"right\" } else { \"left\" }\n",
  "lib.typ": "// @typstream/edu: the vocabulary typstream teaches the model for worksheets, quizzes, exams,\n// lesson plans and handouts (PLAN \u00a78.3). Every function renders in the paged and the HTML target,\n// in English, Arabic and Bengali. Answers appear only when `sys.inputs.showAnswers` is \"true\".\n//\n// The engine preloads this module (`#import \u2026: *`), so documents call `#question` and friends\n// directly. Only the names imported here are public; helpers start with `_`.\n\n#import \"templates.typ\": exam, handout, lesson-plan, quiz, worksheet\n#import \"questions.typ\": matching, mcq, question, true-false\n#import \"answers.typ\": answer, answer-key, answer-lines, answer-space, blank\n#import \"blocks.typ\": callout, instructions, learning-objectives, rubric, student-info\n#import \"drawings.typ\": coordinate-plane, graph-paper, number-line\n#import \"chem.typ\": ce\n",
  "questions.typ": "// Questions: numbered questions with points, multiple choice, true/false, matching.\n#import \"util.typ\": _accent, _answers-shown, _config, _el, _html, _plain, _question, _rule\n#import \"i18n.typ\": _letter, _letter-pattern, _points-text, _word\n#import \"answers.typ\": _record\n\n/// A numbered question. Numbers run through the whole document; points, when given, appear at\n/// the end of the line and count towards the template's total. Put the question's answer space\n/// (`blank`, `answer-lines`, `mcq`, \u2026) inside it. Sub-parts are a numbered list (`+ \u2026`), lettered\n/// `(a)`, `(b)`, \u2026.\n///\n/// - points (int, none): Points the question is worth.\n///\n/// ```example\n/// #question(points: 2)[\n///   What is $3/4$ of 20?\n///   #answer-space(height: 3em, answer: [15])\n/// ]\n/// ```\n#let question(points: none, body) = {\n  _question.step()\n  if points != none { [#metadata(points) <edu-points>] }\n  context {\n    let n = numbering(\"1.\", _question.get().first())\n    let pts = if points != none { [(#_points-text(points, word: _config.get().points-label))] }\n    set enum(numbering: _letter-pattern())\n    if _html() {\n      _el(\"div\", \"edu-question\", {\n        _el(\"span\", \"edu-number\", n)\n        _el(\"div\", \"edu-body\", body)\n        if pts != none { _el(\"span\", \"edu-points\", pts) }\n      })\n    } else {\n      block(width: 100%, above: 1.4em, below: 1.4em, grid(\n        columns: (2em, 1fr, auto),\n        column-gutter: 0.4em,\n        strong(n),\n        body,\n        if pts != none { text(size: 0.85em, fill: _rule, pts) },\n      ))\n    }\n  }\n}\n\n/// The 1-based indices an `answer` names: `2`, `(1, 3)` or a letter such as `\"b\"`.\n#let _choices(answer) = {\n  if answer == none { return () }\n  let index(a) = if type(a) == int { a } else if type(a) == str {\n    let letter = lower(a.trim().trim(\"(\").trim(\")\"))\n    let i = if letter.len() == 1 { \"abcdefghijklmnopqrstuvwxyz\".position(letter) }\n    if i == none { none } else { i + 1 }\n  } else { none }\n  (if type(answer) == array { answer } else { (answer,) }).map(index).filter(i => i != none)\n}\n\n/// A choice marker, circled in the accent color when it is a shown answer.\n#let _marker(m, correct) = if correct {\n  box(stroke: 0.7pt + _accent, radius: 0.6em, inset: (x: 0.2em), outset: (y: 0.15em), text(fill: _accent, m))\n} else { m }\n\n/// Multiple-choice options, lettered (a), (b), \u2026 in the document's language. Give each option as\n/// its own content argument, in brackets, math too: `[$x = 3$]`. `answer` is the correct option's\n/// number, counting from 1, or an array of numbers when several are correct.\n///\n/// - answer (int, array, none): The correct option(s), 1-based.\n/// - columns (int, auto): Options per row. `auto` fits short options on one or two rows.\n///\n/// ```example\n/// #question(points: 1)[\n///   Which planet is closest to the Sun?\n///   #mcq([Venus], [Mercury], [Mars], [Earth], answer: 2)\n/// ]\n/// #question(points: 1)[\n///   Solve $x^2 = 9$.\n///   #mcq([$x = 3$], [$x = 3$ or $x = -3$], [$x = 9$], answer: 2)\n/// ]\n/// ```\n#let mcq(..options, answer: none, columns: auto) = {\n  let options = options.pos()\n  if options.len() == 0 { return }\n  let picks = _choices(answer)\n  if picks.len() > 0 { _record(\"mcq\", context picks.map(_letter).join(\", \")) }\n  let shown = _answers-shown\n  let cols = if columns != auto { columns } else {\n    let longest = calc.max(..options.map(o => _plain(o).clusters().len()))\n    if longest <= 12 { calc.min(options.len(), 4) } else if longest <= 30 { calc.min(options.len(), 2) } else { 1 }\n  }\n  context {\n    let pattern = _letter-pattern()\n    if _html() {\n      _el(\"ol\", (\"edu-mcq\", \"edu-cols-\" + str(cols)), for (i, o) in options.enumerate() {\n        let correct = shown and (i + 1) in picks\n        _el(\"li\", if correct { \"edu-correct\" }, {\n          _el(\"span\", \"edu-marker\", numbering(pattern, i + 1))\n          [ ]\n          o\n        })\n      })\n    } else {\n      block(above: 0.8em, below: 0.8em, grid(\n        columns: (1fr,) * cols,\n        column-gutter: 1em,\n        row-gutter: 0.75em,\n        ..options\n          .enumerate()\n          .map(((i, o)) => {\n            let correct = shown and (i + 1) in picks\n            grid(\n              columns: (auto, 1fr),\n              column-gutter: 0.45em,\n              _marker(numbering(pattern, i + 1), correct),\n              if correct { text(fill: _accent, o) } else { o },\n            )\n          }),\n      ))\n    }\n  }\n}\n\n/// A statement to mark true or false.\n///\n/// - answer (bool, none): Whether the statement is true.\n///\n/// ```example\n/// #true-false(answer: false)[The Sun orbits the Earth.]\n/// ```\n#let true-false(answer: none, body) = {\n  let value = if type(answer) == str { lower(answer) in (\"true\", \"t\", \"yes\") } else { answer }\n  if value != none { _record(\"true-false\", context _word(if value { \"true\" } else { \"false\" })) }\n  let shown = _answers-shown and value != none\n  context {\n    let choice(key) = (key, shown and value == (key == \"true\"))\n    let choices = (choice(\"true\"), choice(\"false\"))\n    if _html() {\n      _el(\"div\", \"edu-tf\", {\n        _el(\"span\", \"edu-tf-statement\", body)\n        _el(\"span\", \"edu-tf-choices\", for (key, correct) in choices {\n          _el(\"span\", if correct { (\"edu-choice\", \"edu-correct\") } else { \"edu-choice\" }, _word(key))\n        })\n      })\n    } else {\n      block(above: 0.7em, below: 0.7em, grid(\n        columns: (1fr, auto),\n        column-gutter: 1em,\n        body,\n        choices.map(((key, correct)) => _marker(_word(key), correct)).join(h(1em)),\n      ))\n    }\n  }\n}\n\n/// A small, stable hash of text, to shuffle matching columns the same way on every compile.\n#let _hash(s) = s.codepoints().fold(7, (h, c) => calc.rem(h * 31 + str.to-unicode(c), 1000003))\n\n/// Two columns to match: give the correct pairs, each as `(left, right)`. The right column is\n/// shuffled (the same way every time) and the key is worked out from the pairs, so write them\n/// in their natural order, correctly matched.\n///\n/// ```example\n/// #matching(\n///   ([perro], [dog]),\n///   ([gato], [cat]),\n///   ([p\u00e1jaro], [bird]),\n/// )\n/// ```\n#let matching(..pairs) = {\n  let pairs = pairs.pos().map(p => if type(p) == array { (p.at(0, default: []), p.at(1, default: [])) } else { (p, []) })\n  let n = pairs.len()\n  if n == 0 { return }\n  // Shuffle the right column by a hash of its text, then rotate it to leave as few pairs as\n  // possible side by side (the first rotation with the fewest wins, so it's deterministic).\n  let sorted = range(n).sorted(key: i => (_hash(_plain(pairs.at(i).at(1))), i))\n  let rotations = range(n).map(r => sorted.slice(r) + sorted.slice(0, r))\n  let fixed(o) = range(n).filter(i => o.at(i) == i).len()\n  let order = rotations.sorted(key: fixed).first()\n  // position-of.at(i): where the match of left item i sits in the right column.\n  let position-of = range(n).map(i => order.position(j => j == i))\n  _record(\"matching\", context range(n).map(i => [#(i + 1)\u2013#_letter(position-of.at(i) + 1)]).join(\", \"))\n  let shown = _answers-shown\n  context {\n    let pattern = _letter-pattern()\n    let rows = range(n).map(i => {\n      let letter = if shown { text(fill: _accent, _letter(position-of.at(i) + 1)) } else { none }\n      (\n        [#(i + 1).],\n        pairs.at(i).at(0),\n        letter,\n        numbering(pattern, i + 1),\n        pairs.at(order.at(i)).at(1),\n      )\n    })\n    if _html() {\n      _el(\"div\", \"edu-matching\", for row in rows {\n        _el(\"span\", \"edu-number\", row.at(0))\n        _el(\"span\", none, row.at(1))\n        _el(\"span\", \"edu-blank\", if row.at(2) == none { [ ] } else { _el(\"span\", \"edu-ink\", row.at(2)) })\n        _el(\"span\", \"edu-marker\", row.at(3))\n        _el(\"span\", none, row.at(4))\n      })\n    } else {\n      block(above: 0.8em, below: 0.8em, grid(\n        columns: (auto, 1fr, 2.5em, auto, 1fr),\n        column-gutter: 0.6em,\n        row-gutter: 0.9em,\n        ..rows\n          .map(row => (\n            row.at(0),\n            row.at(1),\n            box(width: 100%, stroke: (bottom: 0.5pt + _rule), outset: (bottom: 0.25em), align(center, row.at(2))),\n            row.at(3),\n            row.at(4),\n          ))\n          .flatten(),\n      ))\n    }\n  }\n}\n",
  "templates.typ": "// Document templates: page setup, a title block with student fields, page numbers. Applied as\n// the document's first line, `#show: worksheet.with(title: \u2026)`. In HTML there are no pages, so\n// a template writes a <header> and no page rules (no \"page set rule was ignored\" warning).\n#import \"util.typ\": _array, _config, _el, _html, _rule\n#import \"i18n.typ\": _points-text, _word\n#import \"blocks.typ\": instructions as _instructions, student-info\n\n/// The sum of every question's points.\n#let _total() = query(<edu-points>).map(m => m.value).sum(default: 0)\n\n#let _template(\n  body,\n  title: none,\n  subtitle: none,\n  meta: (),\n  details: (),\n  info: none,\n  instructions: none,\n  total: false,\n  running-header: false,\n  paper: \"a4\",\n  lang: auto,\n  points-label: auto,\n) = {\n  let info = if info != none { _array(info) }\n  set document(title: title) if type(title) in (str, content)\n  set text(lang: lang) if lang != auto\n  _config.update(c => (..c, points-label: points-label))\n  context {\n    let total = if total {\n      let t = _total()\n      if t > 0 { [#_word(\"total\"): #_points-text(t, word: points-label)] }\n    }\n    let meta = meta.filter(m => m != none) + if total != none { (total,) } else { () }\n    let details = details.filter(((k, v)) => v != none)\n    if _html() {\n      _el(\"header\", \"edu-header\", {\n        if title != none { html.elem(\"h1\", title) }\n        if subtitle != none { _el(\"p\", \"edu-subtitle\", subtitle) }\n        if meta.len() > 0 { _el(\"p\", \"edu-meta\", meta.join([ \u00b7 ])) }\n        if details.len() > 0 {\n          _el(\"dl\", \"edu-details\", for (k, v) in details {\n            html.elem(\"dt\", _word(k))\n            html.elem(\"dd\", v)\n          })\n        }\n        if info != none { student-info(..info) }\n      })\n      if instructions != none { _instructions(instructions) }\n      body\n    } else {\n      set page(\n        paper: paper,\n        margin: (x: 2cm, top: 2cm, bottom: 2.2cm),\n        header: if running-header {\n          context if counter(page).get().first() > 1 {\n            set text(size: 0.8em)\n            [#title #h(1fr) #_word(\"candidate\"): #box(width: 3.5cm, stroke: (bottom: 0.4pt + _rule))]\n          }\n        },\n        footer: context {\n          let pages = counter(page).final().first()\n          if pages > 1 { align(center, text(size: 0.8em, [#counter(page).display() / #pages])) }\n        },\n      )\n      show heading: set block(above: 1.5em, below: 0.9em)\n      block(width: 100%, below: 1.2em, {\n        align(center, {\n          if title != none { block(below: 0.5em, text(size: 1.6em, weight: \"bold\", title)) }\n          if subtitle != none { block(below: 0.5em, text(size: 1.15em, subtitle)) }\n          if meta.len() > 0 { text(fill: luma(70), meta.join([ #sym.dot.c ])) }\n        })\n        if details.len() > 0 {\n          block(above: 1em, grid(\n            columns: (auto, 1fr, auto, 1fr),\n            column-gutter: (0.5em, 1.5em, 0.5em),\n            row-gutter: 0.6em,\n            ..details.map(((k, v)) => (strong[#_word(k):], v)).flatten(),\n          ))\n        }\n        if info != none { student-info(..info) }\n        line(length: 100%, stroke: 0.6pt + _rule)\n      })\n      if instructions != none { _instructions(instructions) }\n      body\n    }\n  }\n}\n\n/// A worksheet: title, subject and grade, and lines for the student's name, date and class.\n/// Apply it as the document's first line.\n///\n/// - title (content, str, none): The worksheet's title.\n/// - subject (content, str, none): E.g. \"Mathematics\".\n/// - grade (content, str, none): E.g. \"Grade 5\".\n/// - info (array, none): Student fields (see `student-info`); `none` for none.\n/// - instructions (content, none): Instructions shown under the title.\n/// - lang (str, auto): The document's language, e.g. \"ar\" or \"bn\"; sets the text language for the whole document, title included.\n/// - paper (str): Paper size, e.g. \"a4\" or \"us-letter\".\n/// - points-label (str, function, auto): Word for points, e.g. \"marks\"; `auto` is \"points\" in the document's language.\n///\n/// ```example\n/// #show: worksheet.with(title: [Adding Fractions], subject: [Mathematics], grade: [Grade 5])\n/// ```\n#let worksheet(\n  title: none,\n  subject: none,\n  grade: none,\n  info: (\"name\", \"date\", \"class\"),\n  instructions: none,\n  lang: auto,\n  paper: \"a4\",\n  points-label: auto,\n  body,\n) = _template(\n  body,\n  title: title,\n  meta: (subject, grade),\n  info: info,\n  instructions: instructions,\n  lang: lang,\n  paper: paper,\n  points-label: points-label,\n)\n\n/// A quiz: like a worksheet, with the total of the questions' points under the title.\n///\n/// ```example\n/// #show: quiz.with(title: [The Solar System], subject: [Science], grade: [Grade 4])\n/// ```\n#let quiz(\n  title: none,\n  subject: none,\n  grade: none,\n  info: (\"name\", \"date\", \"class\"),\n  instructions: none,\n  lang: auto,\n  paper: \"a4\",\n  points-label: auto,\n  body,\n) = _template(\n  body,\n  title: title,\n  meta: (subject, grade),\n  info: info,\n  instructions: instructions,\n  total: true,\n  lang: lang,\n  paper: paper,\n  points-label: points-label,\n)\n\n/// An exam: title, subject, duration and total points, student fields, an instructions box, and\n/// from page 2 a running header with the title and a candidate box.\n///\n/// - duration (content, str, none): E.g. [2 hours].\n///\n/// ```example\n/// #show: exam.with(\n///   title: [Algebra I Final Examination],\n///   subject: [Mathematics],\n///   duration: [2 hours],\n///   instructions: [Answer *all* questions. Show your working.],\n/// )\n/// ```\n#let exam(\n  title: none,\n  subject: none,\n  grade: none,\n  duration: none,\n  info: (\"name\", \"class\", \"roll\"),\n  instructions: none,\n  lang: auto,\n  paper: \"a4\",\n  points-label: auto,\n  body,\n) = _template(\n  body,\n  title: title,\n  meta: (subject, grade, if duration != none { context [#_word(\"duration\"): #duration] }),\n  info: info,\n  instructions: instructions,\n  total: true,\n  running-header: true,\n  lang: lang,\n  paper: paper,\n  points-label: points-label,\n)\n\n/// A lesson plan for the teacher: title and a table of subject, grade, duration, date and teacher.\n/// Write objectives with `learning-objectives` and the stages as headings.\n///\n/// ```example\n/// #show: lesson-plan.with(title: [The Water Cycle], subject: [Science], grade: [Grade 6], duration: [45 minutes])\n/// ```\n#let lesson-plan(\n  title: none,\n  subject: none,\n  grade: none,\n  duration: none,\n  date: none,\n  teacher: none,\n  lang: auto,\n  paper: \"a4\",\n  body,\n) = _template(\n  body,\n  title: title,\n  details: ((\"subject\", subject), (\"grade\", grade), (\"duration\", duration), (\"date\", date), (\"teacher\", teacher)),\n  lang: lang,\n  paper: paper,\n)\n\n/// A handout or notes for students: title, subtitle, and a line with the subject, grade and teacher.\n///\n/// ```example\n/// #show: handout.with(title: [Photosynthesis], subtitle: [Key ideas], subject: [Biology])\n/// ```\n#let handout(\n  title: none,\n  subtitle: none,\n  subject: none,\n  grade: none,\n  teacher: none,\n  lang: auto,\n  paper: \"a4\",\n  body,\n) = _template(\n  body,\n  title: title,\n  subtitle: subtitle,\n  meta: (subject, grade, teacher),\n  lang: lang,\n  paper: paper,\n)\n",
  "typst.toml": "[package]\nname = \"edu\"\nversion = \"0.1.0\"\nentrypoint = \"lib.typ\"\ndescription = \"Questions, answer spaces, answer keys, callouts, rubrics, drawings and templates for teachers' documents.\"\ncompiler = \"0.15.1\"\n",
  "util.typ": "// Shared helpers: the answer switch, colors, and HTML elements. Not exported by lib.typ.\n#import \"i18n.typ\": _dir\n\n/// Whether answers are shown: the app sets the input `showAnswers` to `\"true\"` and recompiles\n/// (PLAN \u00a78.3). Hidden answers produce no output at all, in either target.\n#let _answers-shown = sys.inputs.at(\"showAnswers\", default: \"false\") == \"true\"\n\n/// Questions, numbered through the whole document.\n#let _question = counter(\"edu-question\")\n\n/// Settings templates make for the whole document, e.g. `points-label`.\n#let _config = state(\"edu-config\", (points-label: auto))\n\n/// The ink answers are written in: a teacher's red pen.\n#let _accent = rgb(\"#c0392b\")\n#let _rule = luma(120)\n#let _faint = luma(200)\n\n/// Whether this compile writes HTML. Needs context; inside `html.frame` it is the paged target.\n#let _html() = target() == \"html\"\n\n/// An HTML element with edu's classes (a string, an array of them, or none). In right-to-left\n/// text it gets `dir=\"rtl\"`, so CSS grids and logical properties flip. Needs context.\n#let _el(tag, cls, body, ..attrs) = {\n  let a = attrs.named()\n  if cls != none { a.insert(\"class\", if type(cls) == array { cls.filter(c => c != none).join(\" \") } else { cls }) }\n  if _dir() == rtl { a.insert(\"dir\", \"rtl\") }\n  html.elem(tag, attrs: a, body)\n}\n\n/// A length as CSS. Relative lengths (`em`) stay relative; ratios become percentages.\n#let _css(l) = {\n  if type(l) == ratio { return repr(l) }\n  if type(l) == relative { return \"calc(\" + repr(l.ratio) + \" + \" + _css(l.length) + \")\" }\n  if l.abs == 0pt { return str(l.em) + \"em\" }\n  if l.em == 0 { return str(calc.round(l.abs.pt(), digits: 2)) + \"pt\" }\n  \"calc(\" + str(l.em) + \"em + \" + str(calc.round(l.abs.pt(), digits: 2)) + \"pt)\"\n}\n\n/// A drawing as inline SVG in HTML, with its description for screen readers; as itself on paper.\n/// Needs context.\n#let _drawing(body, label: \"\", inline: false) = {\n  if not _html() { return body }\n  let attrs = (role: \"img\")\n  if label != \"\" { attrs.insert(\"aria-label\", label) }\n  _el(if inline { \"span\" } else { \"div\" }, \"edu-drawing\", html.frame(body), ..attrs)\n}\n\n/// A length parameter, or `default` while it isn't one yet: cut while streaming, `5em` arrives\n/// as `5` first.\n#let _length(v, default) = if type(v) == length { v } else { default }\n\n/// An array parameter as an array. While a stream is cut, `(2` heals to `(2)`, which is the\n/// number 2, and `(\"name\"` to a string: one item stands for an array of one.\n#let _array(v) = if type(v) == array { v } else if v == none or v == auto { () } else { (v,) }\n\n/// An array-of-pairs parameter (`((1, 2), (3, 4))`) as one. Cut while streaming, `((1, 2` heals to\n/// `((1, 2))`, which is the pair itself.\n#let _pairs(v) = {\n  let v = _array(v)\n  if v.len() > 0 and type(v.at(0)) != array { (v,) } else { v }\n}\n\n/// Plain text of content, for labels and measuring option lengths.\n#let _plain(c) = {\n  if c == none { return \"\" }\n  if type(c) in (str, int, float, bool) { return str(c) }\n  if type(c) == array { return c.map(_plain).join(\" \", default: \"\") }\n  if type(c) != content { return \"\" }\n  if c.func() in ([ ].func(), linebreak, parbreak) { return \" \" }\n  let f = c.fields()\n  if \"text\" in f and type(f.text) == str { return f.text }\n  if \"body\" in f { return _plain(f.body) }\n  if \"children\" in f { return f.children.map(_plain).join(default: \"\") }\n  \"\"\n}\n"
};

export const CSS_SOURCE = "/*\n * @typstream/edu: styles for the HTML that edu's Typst functions write in the HTML target.\n *\n * Everything is scoped to the renderer's root element, `.typstream`, and wrapped in :where()\n * so an app's own rules win without !important. Colors follow the renderer's theme variables\n * and light-dark(), so dark mode works. Logical properties (inline-start/end) flip in\n * right-to-left text, where edu's elements carry dir=\"rtl\".\n */\n\n:where(.typstream) {\n  --edu-ink: light-dark(#c0392b, #ff8a7a);\n  --edu-rule: light-dark(#787878, #8a8a90);\n  --edu-faint: light-dark(#c8c8c8, #4a4a50);\n  --edu-note: light-dark(#2563eb, #7aa7ff);\n  --edu-tip: light-dark(#15803d, #5fd08a);\n  --edu-warning: light-dark(#c2410c, #ff9a5c);\n  --edu-definition: light-dark(#7c3aed, #b69cff);\n  --edu-example: light-dark(#0f766e, #4fd1c5);\n  --edu-remember: light-dark(#b45309, #f5b94a);\n}\n\n/* Template header: title, subject line, student fields. */\n:where(.typstream .edu-header) {\n  margin-block-end: 1.2em;\n  padding-block-end: 0.8em;\n  border-block-end: 1px solid var(--edu-rule);\n  text-align: center;\n}\n:where(.typstream .edu-header) h1 {\n  margin-block: 0 0.3em;\n}\n:where(.typstream .edu-subtitle) {\n  margin-block: 0 0.3em;\n  font-size: 1.15em;\n}\n:where(.typstream .edu-meta) {\n  margin-block: 0;\n  color: var(--typstream-muted, currentColor);\n}\n:where(.typstream .edu-details) {\n  display: grid;\n  grid-template-columns: auto 1fr auto 1fr;\n  gap: 0.4em 0.6em;\n  margin-block: 1em 0;\n  text-align: start;\n}\n:where(.typstream .edu-details) dt {\n  font-weight: bold;\n}\n:where(.typstream .edu-details) dd {\n  margin: 0;\n}\n:where(.typstream .edu-info) {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.6em 1.4em;\n  margin-block: 1em 0;\n  text-align: start;\n}\n:where(.typstream .edu-field) {\n  display: flex;\n  flex: 1 1 8em;\n  align-items: baseline;\n}\n:where(.typstream .edu-field:first-child) {\n  flex-grow: 2.2;\n}\n:where(.typstream .edu-field) .edu-blank {\n  flex: 1;\n  margin-inline-start: 0.4em;\n}\n\n/* Questions: number, body, points. */\n:where(.typstream .edu-question) {\n  display: grid;\n  grid-template-columns: 2em 1fr auto;\n  gap: 0 0.4em;\n  margin-block: 1.2em;\n}\n:where(.typstream .edu-number) {\n  font-weight: bold;\n}\n:where(.typstream .edu-body) > :first-child {\n  margin-block-start: 0;\n}\n:where(.typstream .edu-body) > :last-child {\n  margin-block-end: 0;\n}\n:where(.typstream .edu-points) {\n  color: var(--typstream-muted, currentColor);\n  font-size: 0.85em;\n  white-space: nowrap;\n}\n\n/* Answer spaces. */\n:where(.typstream .edu-blank) {\n  display: inline-block;\n  min-width: 4em;\n  border-block-end: 1px solid var(--edu-rule);\n  text-align: center;\n  line-height: 1.2;\n}\n:where(.typstream .edu-lines) {\n  --edu-line: 2em;\n  margin-block: 0.8em;\n  padding-inline: 0.3em;\n  line-height: var(--edu-line);\n  background-image: linear-gradient(to bottom, transparent calc(var(--edu-line) - 1px), var(--edu-faint) 0);\n  background-size: 100% var(--edu-line);\n}\n:where(.typstream .edu-space) {\n  margin-block: 0.8em;\n}\n:where(.typstream .edu-space.edu-boxed) {\n  padding: 0.4em;\n  border: 1px solid var(--edu-rule);\n}\n:where(.typstream .edu-ink) {\n  color: var(--edu-ink);\n}\n:where(.typstream .edu-answer) {\n  margin-block: 0.8em;\n  padding: 0.4em 0.7em;\n  border-inline-start: 2px solid var(--edu-ink);\n  background: color-mix(in srgb, var(--edu-ink) 8%, transparent);\n  color: var(--edu-ink);\n}\n:where(.typstream .edu-answer-label) {\n  font-weight: bold;\n}\n:where(.typstream .edu-key) {\n  margin-block-start: 2em;\n  color: var(--edu-ink);\n}\n\n/* Multiple choice, true/false, matching. Markers are written out, so lists show none. */\n:where(.typstream .edu-mcq) {\n  display: grid;\n  grid-template-columns: repeat(var(--edu-cols, 1), minmax(0, 1fr));\n  gap: 0.5em 1em;\n  margin-block: 0.7em;\n  padding: 0;\n  list-style: none;\n}\n:where(.typstream .edu-cols-2) {\n  --edu-cols: 2;\n}\n:where(.typstream .edu-cols-3) {\n  --edu-cols: 3;\n}\n:where(.typstream .edu-cols-4) {\n  --edu-cols: 4;\n}\n:where(.typstream .edu-marker) {\n  margin-inline-end: 0.2em;\n}\n:where(.typstream .edu-correct) {\n  color: var(--edu-ink);\n}\n:where(.typstream .edu-correct) .edu-marker,\n:where(.typstream .edu-choice.edu-correct) {\n  padding-inline: 0.2em;\n  border: 1px solid var(--edu-ink);\n  border-radius: 1em;\n}\n:where(.typstream .edu-tf) {\n  display: flex;\n  gap: 1em;\n  justify-content: space-between;\n  align-items: baseline;\n  margin-block: 0.5em;\n}\n:where(.typstream .edu-tf-choices) {\n  display: flex;\n  gap: 1em;\n  white-space: nowrap;\n}\n:where(.typstream .edu-matching) {\n  display: grid;\n  grid-template-columns: auto 1fr 2.5em auto 1fr;\n  gap: 0.6em;\n  align-items: baseline;\n  margin-block: 0.7em;\n}\n\n/* Callouts and instructions: a thin frame with the title set into its top edge, as in the paged\n   target. The page behind is the app's, so nothing can paint over the frame to cut it: the frame\n   is drawn in pieces instead. The box's ::before draws the sides and bottom from just below the\n   top corners; the title's ::before and ::after draw the top corners and the top edge on either\n   side of the text, at the height of its middle. Logical properties mirror it in RTL. */\n:where(.typstream .edu-callout) {\n  --edu-callout: var(--edu-note);\n  --edu-radius: 4px;\n  /* Its own formatting context: the title's negative margin would otherwise collapse through it. */\n  display: flow-root;\n  position: relative;\n  margin-block: 1.6em 1em;\n  padding: 0 0.85em 0.65em;\n}\n:where(.typstream .edu-callout)::before {\n  content: \"\";\n  position: absolute;\n  inset: var(--edu-radius) 0 0;\n  border: 1px solid var(--edu-callout);\n  border-block-start: 0;\n  border-end-start-radius: var(--edu-radius);\n  border-end-end-radius: var(--edu-radius);\n  pointer-events: none;\n}\n/* Without a title, the frame is whole. */\n:where(.typstream .edu-callout:not(:has(> .edu-callout-title))) {\n  margin-block-start: 1em;\n  padding-block-start: 0.65em;\n}\n:where(.typstream .edu-callout:not(:has(> .edu-callout-title)))::before {\n  inset: 0;\n  border-block-start: 1px solid var(--edu-callout);\n  border-radius: var(--edu-radius);\n}\n:where(.typstream .edu-callout) > :last-child {\n  margin-block-end: 0;\n}\n:where(.typstream .edu-callout-title) + * {\n  margin-block-start: 0;\n}\n:where(.typstream .edu-callout-title) {\n  display: flex;\n  gap: 0.35em;\n  margin-block: -0.7em 0.45em;\n  margin-inline: -0.85em;\n  line-height: 1.4em;\n  color: var(--edu-callout);\n  font-weight: bold;\n}\n:where(.typstream .edu-callout-title)::before,\n:where(.typstream .edu-callout-title)::after {\n  content: \"\";\n  height: var(--edu-radius);\n  margin-block-start: 0.7em;\n  border-block-start: 1px solid var(--edu-callout);\n}\n:where(.typstream .edu-callout-title)::before {\n  flex: 0 0 0.55em;\n  border-inline-start: 1px solid var(--edu-callout);\n  border-start-start-radius: var(--edu-radius);\n}\n:where(.typstream .edu-callout-title)::after {\n  flex: 1;\n  border-inline-end: 1px solid var(--edu-callout);\n  border-start-end-radius: var(--edu-radius);\n}\n:where(.typstream .edu-tip) {\n  --edu-callout: var(--edu-tip);\n}\n:where(.typstream .edu-warning) {\n  --edu-callout: var(--edu-warning);\n}\n:where(.typstream .edu-definition) {\n  --edu-callout: var(--edu-definition);\n}\n:where(.typstream .edu-example) {\n  --edu-callout: var(--edu-example);\n}\n:where(.typstream .edu-remember) {\n  --edu-callout: var(--edu-remember);\n}\n:where(.typstream .edu-instructions) {\n  --edu-callout: var(--edu-rule);\n}\n:where(.typstream .edu-instructions) .edu-callout-title {\n  color: inherit;\n}\n\n/* Rubric. */\n:where(.typstream .edu-rubric) {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.9em;\n}\n:where(.typstream .edu-rubric) th,\n:where(.typstream .edu-rubric) td {\n  padding: 0.4em;\n  border: 1px solid var(--edu-rule);\n  text-align: start;\n  vertical-align: top;\n}\n:where(.typstream .edu-rubric) thead th {\n  background: color-mix(in srgb, currentColor 8%, transparent);\n}\n\n/* Drawings are inline SVG drawn in black: give them a light ground in dark mode. */\n:where(.typstream .edu-drawing) {\n  margin-block: 1em;\n}\n:where(.typstream .edu-drawing) svg {\n  max-width: 100%;\n  height: auto;\n  border-radius: 4px;\n  background: light-dark(transparent, #f4f4f5);\n}\n";

